using HartsyInference.Core.Backends.Attention;
using HartsyInference.Core.Tensors;
using Xunit;

namespace HartsyInference.Core.Tests.Backends;

/// <summary>The decode-with-lengths reference against Comfy Kitchen's torch definition (sampled outputs in
/// <see cref="DecodeLengthsKitchenVectors"/>, generated by benchmarks/attention/kitchen_decode_vectors.py), and against
/// what it must reduce to: one contract call when every length is equal, and with the merge reference, a causal decode
/// over the prefix and the step together.</summary>
public sealed class DecodeLengthsReferenceTests
{
    /// <summary>The generator's values in [-1, 1): a 32-bit LCG, exact in F32, identical in the Python script.</summary>
    private static float[] Uniform(int count, uint seed)
    {
        float[] values = new float[count];
        uint state = seed;
        for (int i = 0; i < count; i++)
        {
            state = unchecked(state * 1664525u + 1013904223u);
            values[i] = ((state >> 8) & 0xFFFF) / 32768f - 1f;
        }
        return values;
    }

    /// <summary>F32 to BF16, rounded to nearest even, as torch rounds.</summary>
    private static ushort ToBf16(float value)
    {
        uint u = BitConverter.SingleToUInt32Bits(value);
        return (ushort)((u + 0x7FFFu + ((u >> 16) & 1u)) >> 16);
    }

    private static float FromBf16(ushort bits) => BitConverter.UInt32BitsToSingle((uint)bits << 16);

    private static Tensor Filled(TensorShape shape, DType dtype, uint seed)
    {
        Tensor tensor = new(shape, dtype);
        float[] values = Uniform((int)tensor.ElementCount, seed);
        if (dtype == DType.F32) values.CopyTo(tensor.AsSpan<float>());
        else if (dtype == DType.BF16)
        {
            Span<ushort> bits = tensor.AsSpan<ushort>();
            for (int i = 0; i < values.Length; i++) bits[i] = ToBf16(values[i]);
        }
        else
        {
            Span<ushort> bits = tensor.AsSpan<ushort>();
            for (int i = 0; i < values.Length; i++) bits[i] = BitConverter.HalfToUInt16Bits((Half)values[i]);
        }
        return tensor;
    }

    /// <summary>One decode, built as the generator builds it.</summary>
    private sealed class Decode : IDisposable
    {
        public readonly int Batch, Heads, KvHeads, Dim, Rows, Capacity;
        public readonly Tensor Query, Key, Value, Output;
        public readonly float[] Lse;

        public Decode(int batch, int heads, int kvHeads, int dim, int rows, int capacity, uint seed, DType? dtype = null)
        {
            (Batch, Heads, KvHeads, Dim, Rows, Capacity) = (batch, heads, kvHeads, dim, rows, capacity);
            DType storage = dtype ?? DType.F32;
            Query = Filled(new TensorShape(batch, heads, rows, dim), storage, seed);
            Key = Filled(new TensorShape(batch, kvHeads, capacity, dim), storage, seed + 1);
            Value = Filled(new TensorShape(batch, kvHeads, capacity, dim), storage, seed + 2);
            Output = new Tensor(new TensorShape(batch, rows, heads * dim), storage);
            Lse = new float[batch * heads * rows];
        }

        public void Run(ReadOnlySpan<int> lengths, bool causal, float? scale = null) =>
            DecodeLengthsReference.Run(Output, Query, Key, Value, lengths, causal, Lse, scale);

        /// <summary>The output widened to F32.</summary>
        public float[] Values()
        {
            if (Output.DType == DType.F32) return Output.AsReadOnlySpan<float>().ToArray();
            ReadOnlySpan<ushort> bits = Output.AsReadOnlySpan<ushort>();
            float[] values = new float[bits.Length];
            for (int i = 0; i < bits.Length; i++)
                values[i] = Output.DType == DType.BF16 ? FromBf16(bits[i]) : (float)BitConverter.UInt16BitsToHalf(bits[i]);
            return values;
        }

        public void Dispose()
        {
            foreach (Tensor tensor in (ReadOnlySpan<Tensor>)[Query, Key, Value, Output]) tensor.Dispose();
        }
    }

    private static void AssertLse(ReadOnlySpan<float> expected, ReadOnlySpan<float> actual)
    {
        Assert.Equal(expected.Length, actual.Length);
        for (int i = 0; i < expected.Length; i++)
            if (float.IsNegativeInfinity(expected[i])) Assert.True(float.IsNegativeInfinity(actual[i]), $"LSE {i} is {actual[i]}, expected negative infinity");
            else Assert.True(Math.Abs(expected[i] - actual[i]) <= 2e-5 * Math.Max(1f, Math.Abs(expected[i])), $"LSE {i} is {actual[i]}, expected {expected[i]}");
    }

    /// <summary>Runs one generator case and compares the LSE and the sampled output with the Kitchen's. An F32 output
    /// agrees to 2e-5. A BF16 output is the same BF16 value or the one next to it: the Kitchen rounds an F32 result and the
    /// reference a double one.</summary>
    private static void AssertMatchesKitchen(int index, DType dtype, int batch, int heads, int kvHeads, int dim, int rows, int capacity, int[] lengths,
        bool causal, uint[] expectedOutput, uint[] expectedLse)
    {
        using Decode decode = new(batch, heads, kvHeads, dim, rows, capacity, (uint)(5000 + 100 * index), dtype);
        decode.Run(lengths, causal);
        float[] lse = new float[expectedLse.Length];
        for (int i = 0; i < lse.Length; i++) lse[i] = BitConverter.UInt32BitsToSingle(expectedLse[i]);
        AssertLse(lse, decode.Lse);
        float[] output = decode.Values();
        int width = heads * dim, sampled = width / DecodeLengthsKitchenVectors.ChannelStep;
        Assert.Equal(batch * rows * sampled, expectedOutput.Length);
        for (int row = 0; row < batch * rows; row++)
            for (int c = 0; c < sampled; c++)
            {
                float expected = BitConverter.UInt32BitsToSingle(expectedOutput[row * sampled + c]);
                float actual = output[row * width + c * DecodeLengthsKitchenVectors.ChannelStep];
                string where = $"row {row}, channel {c * DecodeLengthsKitchenVectors.ChannelStep}: {actual}, expected {expected}";
                if (dtype == DType.F32) Assert.True(Math.Abs(expected - actual) <= 2e-5, where);
                else Assert.True(Math.Abs(ToBf16(expected) - ToBf16(actual)) <= 1 && Math.Sign(expected) * Math.Sign(actual) >= 0, where);
            }
    }

    [Fact]
    public void ACausalStaircaseMatchesTheKitchen() =>
        AssertMatchesKitchen(0, DType.F32, 1, 4, 2, 64, 5, 48, [40], true, DecodeLengthsKitchenVectors.CausalStaircase,
            DecodeLengthsKitchenVectors.CausalStaircaseLse);

    [Fact]
    public void LengthsShorterThanTheStepAndLongerThanTheCacheMatchTheKitchen() =>
        AssertMatchesKitchen(1, DType.F32, 2, 4, 2, 64, 6, 32, [3, 99], true, DecodeLengthsKitchenVectors.CausalShortAndOverlongLengths,
            DecodeLengthsKitchenVectors.CausalShortAndOverlongLengthsLse);

    [Fact]
    public void APlainDecodeOverBatchesMatchesTheKitchen() =>
        AssertMatchesKitchen(2, DType.F32, 3, 6, 2, 128, 1, 24, [1, 17, 0], true, DecodeLengthsKitchenVectors.PlainDecodeOverBatches,
            DecodeLengthsKitchenVectors.PlainDecodeOverBatchesLse);

    [Fact]
    public void APrefixOnlyDecodeMatchesTheKitchen() =>
        AssertMatchesKitchen(3, DType.F32, 2, 4, 1, 64, 4, 28, [21, 0], false, DecodeLengthsKitchenVectors.PrefixOnly,
            DecodeLengthsKitchenVectors.PrefixOnlyLse);

    [Fact]
    public void ABf16CausalDecodeAtHeadDim256MatchesTheKitchen() =>
        AssertMatchesKitchen(4, DType.BF16, 1, 4, 2, 256, 3, 40, [37], true, DecodeLengthsKitchenVectors.Bf16CausalHeadDim256,
            DecodeLengthsKitchenVectors.Bf16CausalHeadDim256Lse);

    [Fact]
    public void ABf16PrefixOnlyDecodeOverBatchesMatchesTheKitchen() =>
        AssertMatchesKitchen(5, DType.BF16, 2, 4, 2, 64, 2, 32, [12, 30], false, DecodeLengthsKitchenVectors.Bf16PrefixOnlyOverBatches,
            DecodeLengthsKitchenVectors.Bf16PrefixOnlyOverBatchesLse);

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void WhenEveryLengthIsEqualItIsOneContractCall(bool causal)
    {
        const int Batch = 2, Heads = 6, KvHeads = 2, Dim = 32, Rows = 4, Capacity = 24, Length = 20;
        using Decode decode = new(Batch, Heads, KvHeads, Dim, Rows, Capacity, 800);
        decode.Run([Length, Length], causal);
        using Tensor headMajor = new(decode.Query.Shape, DType.F32);
        AttentionCall call = AttentionCall.FromFlashAttention(headMajor, decode.Query, decode.Key, decode.Value, Length, causal,
            qOffset: causal ? Length - Rows : 0, 1f / MathF.Sqrt(Dim), softcap: 0f, sink: null, slidingWindow: 0, alibiSlopes: null);
        float[] lse = new float[Batch * Heads * Rows];
        AttentionHostReference.Run(in call, lse);
        ReadOnlySpan<float> expected = headMajor.AsReadOnlySpan<float>(), actual = decode.Output.AsReadOnlySpan<float>();
        for (int b = 0; b < Batch; b++)
            for (int h = 0; h < Heads; h++)
                for (int r = 0; r < Rows; r++)
                    Assert.True(expected.Slice(((b * Heads + h) * Rows + r) * Dim, Dim).SequenceEqual(actual.Slice(((b * Rows + r) * Heads + h) * Dim, Dim)),
                        $"batch {b}, head {h}, row {r}");
        Assert.True(lse.AsSpan().SequenceEqual(decode.Lse));
    }

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void RowsPastTheLengthAreNeverRead(bool causal)
    {
        int[] lengths = [13, 5];
        using Decode decode = new(2, 4, 2, 64, 3, 20, 810);
        decode.Run(lengths, causal);
        float[] before = decode.Values(), lseBefore = (float[])decode.Lse.Clone();
        for (int b = 0; b < 2; b++)
            for (int kh = 0; kh < 2; kh++)
            {
                int tail = ((b * 2 + kh) * 20 + lengths[b]) * 64, count = (20 - lengths[b]) * 64;
                decode.Key.AsSpan<float>().Slice(tail, count).Fill(float.NaN);
                decode.Value.AsSpan<float>().Slice(tail, count).Fill(float.NaN);
            }
        decode.Run(lengths, causal);
        Assert.True(before.AsSpan().SequenceEqual(decode.Values()));
        Assert.True(lseBefore.AsSpan().SequenceEqual(decode.Lse));
        Assert.DoesNotContain(decode.Values(), float.IsNaN);
    }

    [Fact]
    public void WithOneRowTheCausalRuleChangesNothing()
    {
        using Decode causal = new(2, 4, 2, 64, 1, 16, 820), plain = new(2, 4, 2, 64, 1, 16, 820);
        causal.Run([9, 16], causal: true);
        plain.Run([9, 16], causal: false);
        Assert.True(causal.Values().AsSpan().SequenceEqual(plain.Values()));
        Assert.True(causal.Lse.AsSpan().SequenceEqual(plain.Lse));
    }

    [Fact]
    public void ARowThatAttendsNothingIsZeroWithAnLseOfNegativeInfinity()
    {
        const int Heads = 4, Rows = 5, Width = Heads * 64;
        using Decode decode = new(2, Heads, 2, 64, Rows, 16, 830);
        decode.Output.AsSpan<float>().Fill(7f);
        // Sequence 0 holds 2 rows, so under the causal rule rows 0 to 2 sit below position 0; sequence 1 is full.
        decode.Run([2, 16], causal: true);
        ReadOnlySpan<float> output = decode.Output.AsReadOnlySpan<float>();
        Assert.Equal(-1, output.Slice(0, 3 * Width).IndexOfAnyExcept(0f));
        Assert.Equal(-1, output.IndexOf(7f));
        for (int h = 0; h < Heads; h++)
            for (int r = 0; r < Rows; r++)
                Assert.Equal(r < 3, float.IsNegativeInfinity(decode.Lse[h * Rows + r]));
        Assert.DoesNotContain(decode.Lse.AsSpan(Heads * Rows).ToArray(), float.IsNegativeInfinity);

        decode.Output.AsSpan<float>().Fill(7f);
        decode.Run([0, 16], causal: false);
        Assert.Equal(-1, decode.Output.AsReadOnlySpan<float>().Slice(0, Rows * Width).IndexOfAnyExcept(0f));
        Assert.All(decode.Lse.AsSpan(0, Heads * Rows).ToArray(), value => Assert.True(float.IsNegativeInfinity(value)));
    }

    [Fact]
    public void ALengthBelowZeroIsZeroAndOneAboveTheCapacityIsTheCapacity()
    {
        using Decode clamped = new(2, 4, 2, 64, 3, 16, 840), exact = new(2, 4, 2, 64, 3, 16, 840);
        clamped.Run([-4, 1000], causal: true);
        exact.Run([0, 16], causal: true);
        Assert.True(exact.Values().AsSpan().SequenceEqual(clamped.Values()));
        Assert.True(exact.Lse.AsSpan().SequenceEqual(clamped.Lse));
    }

    [Fact]
    public void TheLseIsOptional()
    {
        using Decode with = new(1, 4, 2, 64, 3, 16, 850), without = new(1, 4, 2, 64, 3, 16, 850);
        with.Run([11], causal: true);
        DecodeLengthsReference.Run(without.Output, without.Query, without.Key, without.Value, [11], causal: true);
        Assert.True(with.Values().AsSpan().SequenceEqual(without.Values()));
    }

    [Fact]
    public void F16StorageIsReadAndWritten()
    {
        using Decode half = new(1, 4, 2, 64, 3, 16, 860, DType.F16), single = new(1, 4, 2, 64, 3, 16, 860);
        half.Run([14], causal: true);
        single.Run([14], causal: true);
        float[] expected = single.Values(), actual = half.Values();
        // The inputs differ by their F16 rounding (the generator's values carry 16 bits) and the output by its own.
        for (int i = 0; i < expected.Length; i++) Assert.True(Math.Abs(expected[i] - actual[i]) <= 2e-3, $"element {i}: {actual[i]}, expected {expected[i]}");
    }

    /// <summary>The two references together: a prefix-only decode, then the step merge, is the causal decode over a cache
    /// that already holds the step's rows.</summary>
    [Fact]
    public void APrefixOnlyDecodeThenAStepMergeIsTheCausalDecodeOverTheJoinedCache()
    {
        const int Batch = 2, Heads = 4, KvHeads = 2, Dim = 64, Rows = 5, Capacity = 24;
        int[] prefix = [17, 6];
        using Decode step = new(Batch, Heads, KvHeads, Dim, Rows, Capacity, 870);
        step.Run(prefix, causal: false);
        using Tensor stepKey = Filled(new TensorShape(Batch, KvHeads, Rows, Dim), DType.F32, 880);
        using Tensor stepValue = Filled(new TensorShape(Batch, KvHeads, Rows, Dim), DType.F32, 881);
        using Tensor merged = new(step.Output.Shape, DType.F32);
        DecodeMergeReference.StepMerge(merged, step.Output, step.Lse, step.Query, stepKey, stepValue);

        using Decode joined = new(Batch, Heads, KvHeads, Dim, Rows, Capacity + Rows, 870);
        step.Query.AsReadOnlySpan<float>().CopyTo(joined.Query.AsSpan<float>());
        int[] lengths = new int[Batch];
        for (int b = 0; b < Batch; b++)
        {
            lengths[b] = prefix[b] + Rows;
            for (int kh = 0; kh < KvHeads; kh++)
            {
                int from = (b * KvHeads + kh) * Capacity * Dim, to = (b * KvHeads + kh) * (Capacity + Rows) * Dim, stepAt = (b * KvHeads + kh) * Rows * Dim;
                step.Key.AsReadOnlySpan<float>().Slice(from, prefix[b] * Dim).CopyTo(joined.Key.AsSpan<float>().Slice(to));
                step.Value.AsReadOnlySpan<float>().Slice(from, prefix[b] * Dim).CopyTo(joined.Value.AsSpan<float>().Slice(to));
                stepKey.AsReadOnlySpan<float>().Slice(stepAt, Rows * Dim).CopyTo(joined.Key.AsSpan<float>().Slice(to + prefix[b] * Dim));
                stepValue.AsReadOnlySpan<float>().Slice(stepAt, Rows * Dim).CopyTo(joined.Value.AsSpan<float>().Slice(to + prefix[b] * Dim));
            }
        }
        joined.Run(lengths, causal: true);
        ReadOnlySpan<float> expected = joined.Output.AsReadOnlySpan<float>(), actual = merged.AsReadOnlySpan<float>();
        for (int i = 0; i < expected.Length; i++) Assert.True(Math.Abs(expected[i] - actual[i]) <= 2e-5, $"element {i}: {actual[i]}, expected {expected[i]}");
    }

    [Fact]
    public void MalformedCallsAreRefused()
    {
        using Decode decode = new(2, 4, 2, 64, 3, 16, 890);
        Tensor o = decode.Output, q = decode.Query, k = decode.Key, v = decode.Value;
        int[] lengths = [9, 16];
        Assert.Throws<ArgumentException>(() => DecodeLengthsReference.Run(o, q, k, v, [9], true));
        Assert.Throws<ArgumentException>(() => DecodeLengthsReference.Run(o, q, k, v, lengths, true, new float[5]));
        Assert.Throws<ArgumentException>(() => DecodeLengthsReference.Run(o, q, k, v, lengths, true, scale: float.NaN));
        using Tensor headMajor = new(q.Shape, DType.F32);
        Assert.Throws<ArgumentException>(() => DecodeLengthsReference.Run(headMajor, q, k, v, lengths, true));
        using Tensor shorter = new(new TensorShape(2, 2, 12, 64), DType.F32);
        Assert.Throws<ArgumentException>(() => DecodeLengthsReference.Run(o, q, k, shorter, lengths, true));
        using Tensor threeKvHeads = new(new TensorShape(2, 3, 16, 64), DType.F32);
        Assert.Throws<ArgumentException>(() => DecodeLengthsReference.Run(o, q, threeKvHeads, threeKvHeads, lengths, true));
        using Tensor oneBatch = new(new TensorShape(1, 2, 16, 64), DType.F32);
        Assert.Throws<ArgumentException>(() => DecodeLengthsReference.Run(o, q, oneBatch, oneBatch, lengths, true));
        using Tensor otherDim = new(new TensorShape(2, 2, 16, 32), DType.F32);
        Assert.Throws<ArgumentException>(() => DecodeLengthsReference.Run(o, q, otherDim, otherDim, lengths, true));
        Assert.Throws<ArgumentException>(() => DecodeLengthsReference.Run(q, q, k, v, lengths, true));
    }
}
